function openModal(kind,idValue=''){lastTrigger=document.activeElement;modal={kind,id:idValue,dogId:idValue};document.body.classList.add('modal-open');render();queueMicrotask(()=>root.querySelector('[role="dialog"]')?.focus());}
function stopScanner(){try{scannerControls?.stop();}catch{scannerControls=null;}scannerControls=null;const panel=root.querySelector('[data-scanner]');if(panel)panel.hidden=true;}
