function bindAttachmentHooks(){root.querySelectorAll('[data-view-attachment]').forEach(x=>x.onclick=()=>openModal('attachmentView',x.dataset.viewAttachment));root.querySelectorAll('[data-ocr-attachment]').forEach(x=>x.onclick=()=>{const a=state.attachments.find(v=>v.id===x.dataset.ocrAttachment);if(a?.ocrAt)openModal('ocrReview',a.id);else runAttachmentOcr(a?.id);});root.querySelectorAll('[data-delete-attachment]').forEach(x=>x.onclick=async()=>{const a=state.attachments.find(v=>v.id===x.dataset.deleteAttachment);if(!a||!window.confirm(`${a.kind}を削除しますか？`))return;const next=structuredClone(state);next.attachments=next.attachments.filter(v=>v.id!==a.id);next.health=next.health.map(h=>h.id===a.recordId?{...h,attachmentStatus:next.attachments.some(v=>v.recordId===h.id)?'添付あり':'未添付'}:h);await commit(next,'書類画像を削除しました');});}
